// hunt_and_battle.rs:28  EpicHuntAndBattlePlan::sub_plan
// self = EpicHuntAndBattlePlan { target_bush: Option<usize> }

// [29행] 내 챔피언 얻기 (없으면 패닉)
team = player.info.team                       // PlayerState+0x930, >=2 면 bounds panic
pos  = player.info.position.as_index()        // PlayerState+0x9c0, 0..=4 (Top/Jungle/Mid/Bottom/Support)
champ = data.cache.player_champion[team][pos].unwrap()   // cache+0x1e0 + team*40 + pos*8

// [31행] 내 체력 비율(%) — 정수 나눗셈
if champ.stat_cached.hp == 0 { panic!(div by zero) }
hp_ratio = champ.hp * 100 / champ.stat_cached.hp     // 0x670 * 100 / 0x628

// [32행] 에픽 몬스터 엔티티 (없을 수 있음)
game = data.cache.game                        // &dyn AbstractGame (데이터ptr, vtable)
moba = (vt+0x40)(game) .as_moba().unwrap()    // GameMode 가 Moba 가 아니면 패닉
live = moba.jungle_runner.epic.live_list      // Vec<usize> @ MobaMode+0x198
epic: Option<&Entity> =
    if live.len == 0 { None }
    else { (vt+0x1f0)(game, live[0]) }         // 첫 원소만 본다 (and_then + closure$0)

// [33행] 우리 팀 분수(fountain) 사각형
(lx, ly, rx, ry) = data.context.map.fountains[team]   // MapDef+0x6d70 + team*32

// [34행] 분수(회복지대) 안에 있는가 — x 범위부터 검사, 실패하면 y 는 안 봄
is_in_heal_area = (champ.x >= lx && champ.x <= rx) && (champ.y >= ly && champ.y <= ry)

// [35행] 지금 아이템을 올릴 수 있는가
can_upgrade_item = game_ai::upgrade_item(version, rnd, player, game, data.context).is_some()
                   // 반환 Option<(usize,usize)> 의 존재 여부만 쓴다 (내용은 버림)

// [36행] 에픽이 '무손상'(= 아무도 안 건드림)이고, 지금 본진으로 돌아갈 이유가 있으면 귀환
if epic.is_some_and(|e| e.hp == e.stat_cached.hp)
   && ( hp_ratio < 51                                        // 체력 50% 이하
        || can_upgrade_item                                  // 살 아이템이 있음
        || (champ.hp < champ.stat_cached.hp && is_in_heal_area) )  // 다쳤는데 이미 분수 안
{
    return SubPlan::Recall            // tag=5, 페이로드 없음(RecallSubPlan = ZST)
}
// (IR 상 결합 순서: ((champ.hp<max && is_in_heal_area) || (hp_ratio<51 || can_upgrade_item)))

// [41행] 에픽 타이밍 게이트 && 매복할 부시가 지정돼 있는가 (단축평가 AND)
if  goal_data.epic.epic_ally_tick + data.context.setting.tick_per_second
        > goal_data.epic.epic_ally_killed_tick
    && self.target_bush.is_some()
{
    // [42~43행] 부시에 숨어 매복
    target_bush = self.target_bush.unwrap()       // self+0x8
    return SubPlan::Hide(HideSubPlan {
        bush: target_bush,                        // ret+0x8
        out_line: AroundBushOutlineType::Outline, // ret+0x10 = 1
        check_move: false,                        // ret+0x11 = 0
        enemy_spotted_me: false,                  // ret+0x12 = 0
    })                                            // tag=9
} else {
    // [47행] 그 외에는 에픽 사냥
    return SubPlan::EpicHunt(EpicHuntSubPlan { need_recall: false })  // tag=11, ret+0x8 = 0
}

// 정리: 이 함수의 출력은 Recall / Hide / EpicHunt 3가지뿐이다.
//  - Recall 조건이 최우선이고, 그 다음이 Hide, 나머지 전부 EpicHunt(기본값).
//  - epic 이 None 이거나 에픽이 이미 피해를 입었으면 36행 게이트는 무조건 거짓 → 절대 Recall 안 함.
